def keys(self):
    """ Return the keys of the record.

    :return: list of key names
    """
    return list(self._record.keys())

def index(self, key):
    """ Return the index of the given item.

    :param key: a key
    :return: index
    :rtype: int
    """
    try:
        return self._keys.index(key)
    except ValueError:
        raise KeyError(f'Key not found: {key}')

def values(self, *keys):
    """ Return the values of the record, optionally filtering to
    include only certain values by index or key.

    :param keys: indexes or keys of the items to include; if none
                 are provided, all values will be included
    :return: list of values
    :rtype: list
    """
    if not keys:
        return list(self._record.values())
    else:
        return [self._record[key] for key in keys if key in self._record]

def data(self, *keys):
    """ Return the keys and values of this record as a dictionary,
    optionally including only certain values by index or key. Keys
    provided in the items that are not in the record will be
    inserted with a value of :const:`None`; indexes provided
    that are out of bounds will trigger an :exc:`IndexError`.

    :param keys: indexes or keys of the items to include; if none
                  are provided, all values will be included
    :return: dictionary of values, keyed by field name
    :raises: :exc:`IndexError` if an out-of-bounds index is specified
    """
    result = {}
    for key in keys:
        if isinstance(key, int):
            if key >= len(self._fields):
                raise IndexError(f"Index {key} is out of bounds")
            result[self._fields[key]] = self._values[key]
        elif isinstance(key, str):
            if key in self._fields:
                index = self._fields.index(key)
                result[key] = self._values[index]
            else:
                result[key] = None
        else:
            raise ValueError(f"Key {key} must be an integer index or a string field name")
    if not keys:
        result = dict(zip(self._fields, self._values))
    return result

def point_type(name, fields, srid_map):
    """ Dynamically create a Point subclass.
    """

    class _Point(Point):
        __slots__ = tuple(fields)
        _srid_map = srid_map

        def __init__(self, *args):
            if len(args) != len(fields):
                raise TypeError(f"Expected {len(fields)} arguments, got {len(args)}")
            for field, value in zip(fields, args):
                setattr(self, field, value)

        def __repr__(self):
            field_values = ", ".join(f"{field}={getattr(self, field)!r}" for field in fields)
            return f"{name}({field_values})"

    _Point.__name__ = name
    return _Point

def deprecated(message):
    """ Decorator for deprecating functions and methods.

    ::

        @deprecated("'foo' has been deprecated in favour of 'bar'")
        def foo(x):
            pass

    """
    def decorator(func):
        def wrapper(*args, **kwargs):
            import warnings
            warnings.warn(message, category=DeprecationWarning, stacklevel=2)
            return func(*args, **kwargs)
        return wrapper
    return decorator

