def cached(cache, key=hashkey, lock=None):
    """Decorator to wrap a function with a memoizing callable that saves
    results in a cache.

    """
    def decorator(func):
        if cache is None:
            def wrapper(*args, **kwargs):
                return func(*args, **kwargs)
        elif lock is None:
            def wrapper(*args, **kwargs):
                k = key(*args, **kwargs)
                try:
                    return cache[k]
                except KeyError:
                    pass  # key not found
                v = func(*args, **kwargs)
                try:
                    cache[k] = v
                except ValueError:
                    pass  # value too large
                return v
        else:
            def wrapper(*args, **kwargs):
                k = key(*args, **kwargs)
                try:
                    with lock:
                        return cache[k]
                except KeyError:
                    pass  # key not found
                v = func(*args, **kwargs)
                try:
                    with lock:
                        cache[k] = v
                except ValueError:
                    pass  # value too large
                return v
        return _update_wrapper(wrapper, func)
    return decorator

def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm with a per-item time-to-live (TTL) value.
    """
    from functools import lru_cache, wraps
    from time import monotonic
    from collections import OrderedDict

    def decorator(func):
        cache = OrderedDict()

        @wraps(func)
        def wrapper(*args, **kwargs):
            if typed:
                key = (args, tuple(sorted(kwargs.items())))
            else:
                key = args + tuple(kwargs.items())

            current_time = timer()

            # Remove expired items
            to_remove = []
            for k, (value, expiry) in cache.items():
                if expiry <= current_time:
                    to_remove.append(k)
                else:
                    break
            for k in to_remove:
                del cache[k]

            # Check if the key is in the cache and not expired
            if key in cache:
                value, expiry = cache[key]
                if expiry > current_time:
                    return value

            # Call the function and update the cache
            value = func(*args, **kwargs)
            cache[key] = (value, current_time + ttl)

            # Maintain the cache size
            if len(cache) > maxsize:
                cache.popitem(last=False)

            return value

        def cache_clear():
            cache.clear()

        wrapper.cache_clear = cache_clear
        return wrapper

    return decorator

def lru_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm.

    """
    from functools import lru_cache as _lru_cache

    def decorator(func):
        return _lru_cache(maxsize=maxsize, typed=typed)(func)

    return decorator

def lfu_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Frequently Used (LFU)
    algorithm.

    """
    from collections import defaultdict

    def decorator(func):
        cache = {}
        frequency = defaultdict(int)
        if typed:
            def key(args, kwargs):
                return args, tuple(sorted(kwargs.items()))
        else:
            def key(args, kwargs):
                return args + tuple(sorted(kwargs.items()))

        def wrapper(*args, **kwargs):
            k = key(args, kwargs)
            if k in cache:
                frequency[k] += 1
                return cache[k]
            elif len(cache) < maxsize:
                result = func(*args, **kwargs)
                cache[k] = result
                frequency[k] = 1
                return result
            else:
                # Find and remove the least frequently used item
                lfu_key = min(cache, key=lambda x: frequency[x])
                del cache[lfu_key]
                del frequency[lfu_key]
                result = func(*args, **kwargs)
                cache[k] = result
                frequency[k] = 1
                return result

        return _update_wrapper(wrapper, func)
    return decorator

def popitem(self):
    """Remove and return the `(key, value)` pair first inserted."""
    if not self:
        raise KeyError('dictionary is empty')
    first_key = next(iter(self))
    return first_key, self.pop(first_key)

