def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    num_objects = 0
    good_objects = 0

    # Example logic for validation
    for obj in self._storage_root.objects:
        num_objects += 1
        is_valid = True

        if validate_objects:
            if not self._validate_object(obj):
                is_valid = False
                if show_warnings:
                    print(f"Warning: Object {obj.id} is invalid.")

        if check_digests:
            if not self._check_digest(obj):
                is_valid = False
                if show_warnings:
                    print(f"Warning: Digest mismatch for object {obj.id}.")

        if is_valid:
            good_objects += 1

    return num_objects, good_objects

def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    content_digests = {}

    for version_dir in version_dirs:
        try:
            with open(os.path.join(version_dir, 'inventory'), 'r') as f:
                inventory = json.load(f)
        except FileNotFoundError:
            raise ValueError(f"Inventory missing for version {version_dir}")
        except json.JSONDecodeError:
            raise ValueError(f"Invalid JSON in inventory for version {version_dir}")

        # Assume inventory is a dict with 'content' mapping to a list of digests
        if 'content' not in inventory:
            raise ValueError(f"Content list missing in inventory for version {version_dir}")

        for digest in inventory['content']:
            if digest in content_digests and content_digests[digest] != version_dir:
                print(f"Digest {digest} from version {version_dir} differs from original version {content_digests[digest]}")
            if digest not in content_digests:
                content_digests[digest] = version_dir

