def deep_merge_nodes(nodes):
    '''
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.
    '''
    from ruamel.yaml.nodes import MappingNode, ScalarNode

    merged_dict = {}
    for key_node, value_node in nodes:
        key = key_node.value
        if key in merged_dict:
            if isinstance(value_node, MappingNode) and isinstance(merged_dict[key][1], MappingNode):
                # Deep merge the MappingNode values
                merged_value = merged_dict[key][1].value.copy()
                for new_key_node, new_value_node in value_node.value:
                    new_key = new_key_node.value
                    found = False
                    for i, (existing_key_node, existing_value_node) in enumerate(merged_value):
                        if existing_key_node.value == new_key:
                            if isinstance(new_value_node, MappingNode) and isinstance(existing_value_node, MappingNode):
                                # Recursively deep merge nested MappingNodes
                                merged_value[i] = (existing_key_node, deep_merge_nodes([(existing_key_node, existing_value_node), (new_key_node, new_value_node)])[0][1])
                            else:
                                # Replace the existing value with the new value
                                merged_value[i] = (new_key_node, new_value_node)
                            found = True
                            break
                    if not found:
                        merged_value.append((new_key_node, new_value_node))
                merged_dict[key][1].value = merged_value
            else:
                # Replace non-MappingNode values with the last one encountered
                merged_dict[key] = (key_node, value_node)
        else:
            merged_dict[key] = (key_node, value_node)

    return list(merged_dict.values())

