def size_to_bytes(size: str) -> int:
    """Convert human readable file size to bytes.

    Resulting value is an approximation as input value is in most case rounded.

    Args:
        size: A string representing a human readable file size (eg: '500K')

    Returns:
        A decimal representation of file size

        Examples::

            >>> size_to_bytes("500")
            500
            >>> size_to_bytes("1K")
            1000
    """
    # Define the size units and their corresponding byte values
    units = {
        'K': 1000, 'KB': 1000,
        'M': 1000**2, 'MB': 1000**2,
        'G': 1000**3, 'GB': 1000**3,
        'T': 1000**4, 'TB': 1000**4,
        'P': 1000**5, 'PB': 1000**5,
        'E': 1000**6, 'EB': 1000**6,
        'Z': 1000**7, 'ZB': 1000**7,
        'Y': 1000**8, 'YB': 1000**8
    }

    if size.isdigit():
        return int(size)

    # Convert size to uppercase to handle case insensitivity
    size = size.upper()

    # Extract the number and unit from the size string
    for unit, byte_value in units.items():
        if size.endswith(unit):
            number = size[:-len(unit)].strip()
            try:
                return int(float(number) * byte_value)
            except ValueError:
                raise ValueError(f"Invalid size format: {size}")

    # If no unit is found, assume it's a plain number
    try:
        return int(size)
    except ValueError:
        raise ValueError(f"Invalid size format: {size}")

def _dictsum(dicts):
    """
    Combine values of the dictionaries supplied by iterable dicts.

    >>> _dictsum([{'a': 1, 'b': 2}, {'a': 5, 'b': 0}])
    {'a': 6, 'b': 2}
    """
    result = {}
    for d in dicts:
        for key, value in d.items():
            if key in result:
                result[key] += value
            else:
                result[key] = value
    return result

