        try:
            if verbose:
                print(f"Running command: {' '.join(full_command)}")
            with subprocess.Popen(full_command, cwd=cwd, env=env, stdout=subprocess.PIPE, stderr=subprocess.PIPE if not hide_stderr else subprocess.DEVNULL) as process:
                stdout, stderr = process.communicate()
                if process.returncode != 0:
                    error_message = f"Command {' '.join(full_command)} failed with return code {process.returncode}"
                    if stderr:
                        error_message += f"\nError: {stderr.decode()}"
                    raise subprocess.CalledProcessError(process.returncode, full_command, output=stdout, stderr=stderr)
                if verbose and stdout:
                    print(stdout.decode())
        except subprocess.CalledProcessError as e:
            print(e)
            raise

