def validate_from_content(cls, spec_content=None):
    """validates that spec (YAML) content has all required fields

    :param spec_content: content of spec file
    :raise IRValidatorException: when mandatory data
    is missing in spec file
    :return: Dictionary with data loaded from a spec (YAML) file
    """
    import yaml

    if spec_content is None:
        raise ValueError("spec_content argument must be supplied")

    try:
        spec_data = yaml.safe_load(spec_content)
    except yaml.YAMLError as e:
        raise IRValidatorException(f"Error parsing YAML content: {str(e)}")

    required_fields = {'field1', 'field2', 'field3'}  # Example required fields
    missing_fields = required_fields - spec_data.keys()

    if missing_fields:
        raise IRValidatorException(f"Mandatory fields missing: {', '.join(missing_fields)}")

    return spec_data

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files. """
    if 'include' in parser_dict:
        for include_key in parser_dict['include']:
            parser_dict.update(self.spec[include_key])
        del parser_dict['include']

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources. """
    defaults = {}
    for arg_name, arg_spec in self.spec.items():
        if 'default' in arg_spec:
            defaults[arg_name] = arg_spec['default']
    # Additional logic to resolve from other sources can be added here
    return defaults

def get_deprecated_args(self):
    """Returning dict with options which deprecate others. """
    return {
        'old_arg': 'new_arg',
        'deprecated_option': 'current_option'
    }

def validate_arg_deprecation(self, cli_args, answer_file_args):
    """Validates and prints the deprecated arguments.

    :param cli_args: the dict of arguments from cli
    :param answer_file_args:  the dict of arguments from files
    """
    deprecated_args = {
        'old_arg1': 'new_arg1',
        'old_arg2': 'new_arg2'
    }  # Example deprecated arguments mapping

    for old_arg, new_arg in deprecated_args.items():
        if old_arg in cli_args:
            print(f"Warning: '{old_arg}' has been deprecated in favor of '{new_arg}'. Please update your CLI arguments.")
        if old_arg in answer_file_args:
            print(f"Warning: '{old_arg}' has been deprecated in favor of '{new_arg}'. Please update your answer files.")

def get_parser_option_specs(self, command_name):
    """Gets all the options for the specified command

    :param command_name: the command name (main, virsh, ospd, etc...)
    :return: the list of all command options
    """
    if command_name == "main":
        return [
            {"name": "--verbose", "action": "store_true", "help": "Increase verbosity"},
            {"name": "--config", "type": "str", "help": "Path to configuration file"}
        ]
    elif command_name == "virsh":
        return [
            {"name": "--connect", "type": "str", "help": "Hypervisor connection URI"},
            {"name": "--read-only", "action": "store_true", "help": "Open read-only connection"}
        ]
    elif command_name == "ospd":
        return [
            {"name": "--port", "type": "int", "default": 12345, "help": "Server port number"},
            {"name": "--address", "type": "str", "default": "127.0.0.1", "help": "Server bind address"}
        ]
    else:
        return []

def get_option_spec(self, command_name, argument_name):
    """Gets the specification for the specified option name. """
    if command_name in self.commands:
        command = self.commands[command_name]
        if argument_name in command.options:
            return command.options[argument_name]
    return None

def get_silent_args(self, args):
    """list of silenced argument

    :param args: The received arguments.
    :return: list, silenced argument names
    """
    silenced_args = []
    for arg, value in vars(args).items():
        if value is None or value is False:
            silenced_args.append(arg)
    return silenced_args

def validate_requires_args(self, args):
    """Check if all the required arguments have been provided. """
    for arg_name in self.required_args:
        if arg_name not in args:
            raise ValueError(f"Missing required argument: {arg_name}")

def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    """
    for arg_name, arg_value in args.items():
        if isinstance(arg_value, str) and 'length' in self.parsed_yaml.get('args', {}).get(arg_name, {}):
            max_length = self.parsed_yaml['args'][arg_name]['length']
            if len(arg_value) > max_length:
                raise ValueError(f"Argument '{arg_name}' is longer than the maximum allowed length of {max_length}.")

def validate_choices_args(self, args):
    """Check if value of choice arguments is one of the available choices.

    :param args: The received arguments.
    """
    for arg_name, arg_value in args.items():
        if arg_name in self.choices:
            if arg_value not in self.choices[arg_name]:
                raise ValueError(f"Invalid choice for {arg_name}: {arg_value}. Available choices are {self.choices[arg_name]}")

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    for arg_name, arg_value in args.items():
        min_value = getattr(self, f"{arg_name}_min", None)
        max_value = getattr(self, f"{arg_name}_max", None)
        if min_value is not None and arg_value < min_value:
            raise ValueError(f"The value of {arg_name} must be at least {min_value}, got {arg_value}")
        if max_value is not None and arg_value > max_value:
            raise ValueError(f"The value of {arg_name} must be at most {max_value}, got {arg_value}")

def get_nested_custom_and_control_args(self, args):
    """Split input arguments to control nested and custom.

    Controls arguments: control the IR behavior. These arguments
        will not be put into the spec yml file
    Nested arguments: are used by the Ansible playbooks and will be put
        into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
        normal nested usage.

    :param args: the collected list of args.
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """
    control_args = {}
    nested_args = {}

    for arg, value in args.items():
        if arg.startswith('control_'):
            control_args[arg] = value
        elif arg.startswith('custom_'):
            nested_args[arg[len('custom_'):]] = value
        else:
            nested_args[arg] = value

    return control_args, nested_args

def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra-vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    """
    if extra_vars is None:
        extra_vars = []
    for extra_var in extra_vars:
        vars_dict.update(extra_var)
    return vars_dict

def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    parser = self.parsers[parser_name]
    for action in parser._actions:
        if action.dest in values_dict:
            try:
                values_dict[action.dest] = action.type(values_dict[action.dest])
            except (ValueError, TypeError):
                # If conversion fails, keep the original value
                pass

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    import json

    def flatten_dict(d, parent_key='', sep='_'):
        items = []
        for k, v in d.items():
            new_key = f"{parent_key}{sep}{k}" if parent_key else k
            if isinstance(v, dict):
                items.extend(flatten_dict(v, new_key, sep=sep).items())
            else:
                items.append((new_key, v))
        return dict(items)

    spec_path = os.path.join(plugin_dir, 'plugin_spec.json')
    with open(spec_path, 'r') as file:
        plugin_spec = json.load(file)

    return flatten_dict(plugin_spec)

def inject_config(self):
    """Set the environment variable for config path, if it is undefined."""
    if 'CONFIG_PATH' not in os.environ:
        os.environ['CONFIG_PATH'] = self.config_path

def strip_root(path, root):
    """Remove root from path, throw exception on failure."""
    if not path.startswith(root):
        raise ValueError(f"Path '{path}' does not start with root '{root}'")
    return path[len(root):].lstrip(os.sep)
